int map_user_iov(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask)
{
    size_t total_len = iov_iter_count(iter);
    size_t offset = 0;
    size_t len;
    struct bio *bio = NULL;
    struct bio *prev = NULL;
    int ret = 0;

    if (!q || !rq || !map_data || !iter || !iov_iter_count(iter))
        return -EINVAL;

    while (iov_iter_next_segment(iter, &offset, &len)) {
        struct bio *new_bio;

        if (len == 0)
            continue;

        new_bio = bio_kmalloc(gfp_mask, 1);
        if (!new_bio) {
            ret = -EINVAL;
            goto cleanup;
        }

        new_bio->bi_iter = (struct bvec_iter) {
            .bi_size = len,
            .bi_bvec = 0,
            .bi_idx = 0,
        };

        new_bio->bi_io_vec = kmalloc(sizeof(struct bio_vec), gfp_mask);
        if (!new_bio->bi_io_vec) {
            bio_put(new_bio);
            ret = -EINVAL;
            goto cleanup;
        }

        new_bio->bi_io_vec->bv_page = map_data->pages;
        new_bio->bi_io_vec->bv_len = len;
        new_bio->bi_io_vec->bv_offset = offset;

        if (prev) {
            prev->bi_next = new_bio;
        } else {
            rq->bio = new_bio;
        }

        prev = new_bio;
    }

    if (!rq->bio) {
        ret = -EINVAL;
        goto cleanup;
    }

    return 0;

 cleanup:
    while (rq->bio) {
        struct bio *next = rq->bio->bi_next;
        bio_put(rq->bio);
        rq->bio = next;
    }
    return ret;
}
